import 'dart:async';

import 'package:flutter/material.dart';

import '../i18n/aurora_i18n.dart';
import '../state/app_state.dart';
import '../widgets/common.dart';
import 'board_index.g.dart';

export 'board_package.dart';

// Game boards are split into one deferred library per game package
// (board_index.g.dart, regenerated by `dart run tool/gen_boards.dart`), so the
// web client's main.dart.js no longer contains the UI of all 400+ games.
// A package is downloaded the first time one of its games is shown (or earlier
// via [preloadBoard], e.g. as soon as a room for that game is entered).

final Map<int, Future<void>> _loading = {};
final Map<String, BoardBuilder> _loaded = {};

/// Whether this client knows a board for [gameId] (loaded or not).
bool hasBoard(String gameId) => boardPackageOf.containsKey(gameId);

/// The board builder for [gameId] if its package is already loaded.
BoardBuilder? loadedBoard(String gameId) => _loaded[gameId];

/// Every board builder loaded so far (all of them after [loadAllBoardPackages]).
Map<String, BoardBuilder> get boardRegistry => Map.unmodifiable(_loaded);

/// Starts downloading the board package of [gameId]; safe to call repeatedly.
Future<void> preloadBoard(String gameId) {
  final i = boardPackageOf[gameId];
  if (i == null) return Future.value();
  return _loadPackage(i);
}

/// Loads every board package (tests, tools).
Future<void> loadAllBoardPackages() => Future.wait([for (var i = 0; i < boardPackages.length; i++) _loadPackage(i)]);

Future<void> _loadPackage(int i) {
  final pending = _loading[i];
  if (pending != null) return pending;
  final p = boardPackages[i];
  final f = p.load().then((_) => _loaded.addAll(p.boards()));
  _loading[i] = f;
  // A failed download (flaky network) may be retried later.
  unawaited(f.then((_) {}, onError: (Object _) {
    _loading.remove(i);
  }));
  return f;
}

/// The game board for [g]. Shows a small loader while the game's package is
/// downloaded, and skips rebuilding the board when only unrelated app state
/// (chat, voice, lobby list...) changed.
Widget buildBoard(GameContext g) => _BoardHost(g);

class _BoardHost extends StatefulWidget {
  final GameContext g;
  const _BoardHost(this.g);
  @override
  State<_BoardHost> createState() => _BoardHostState();
}

class _BoardHostState extends State<_BoardHost> {
  Widget? _cached;
  _MemoKey? _key;
  String? _loadingId;
  Object? _error;

  @override
  Widget build(BuildContext context) {
    final g = widget.g;
    final id = g.state.game;
    final builder = _loaded[id];
    if (builder == null) {
      _cached = null;
      _key = null;
      if (!hasBoard(id)) {
        return Center(child: Text(auroraT('客户端不支持该游戏：{0}，请更新客户端', [id]), textAlign: TextAlign.center));
      }
      _startLoad(id);
      return _BoardLoading(error: _error, onRetry: () => setState(() => _error = null));
    }
    final key = _MemoKey.of(g);
    final cached = _cached;
    if (cached != null && key == _key) return cached; // identical widget => subtree not rebuilt
    _key = key;
    return _cached = RepaintBoundary(child: builder(g));
  }

  void _startLoad(String id) {
    if (_error != null || _loadingId == id) return;
    _loadingId = id;
    preloadBoard(id).then((_) {
      if (mounted) setState(() => _loadingId = null);
    }, onError: (Object e) {
      if (mounted) {
        setState(() {
          _loadingId = null;
          _error = e;
        });
      }
    });
  }
}

/// Inputs a board's output depends on besides inherited widgets (theme,
/// media query, ...) which Flutter tracks by itself. Boards must render purely
/// from GameContext (see GAME_DEV_GUIDE.md), so as long as these are the same
/// objects the previously built board can be reused as-is.
class _MemoKey {
  final GameState state;
  final bool replay;
  final Object? options;
  final String themeId;
  const _MemoKey(this.state, this.replay, this.options, this.themeId);

  factory _MemoKey.of(GameContext g) => _MemoKey(
        g.state,
        g.replay,
        g.optionsOverride ?? g.app.local?.options ?? g.app.room?['options'],
        g.app.themeId,
      );

  @override
  bool operator ==(Object other) =>
      other is _MemoKey &&
      identical(other.state, state) &&
      other.replay == replay &&
      identical(other.options, options) &&
      other.themeId == themeId;

  @override
  int get hashCode => Object.hash(identityHashCode(state), replay, identityHashCode(options), themeId);
}

class _BoardLoading extends StatelessWidget {
  final Object? error;
  final VoidCallback onRetry;
  const _BoardLoading({required this.error, required this.onRetry});

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          if (error == null) ...[
            const SizedBox(width: 32, height: 32, child: CircularProgressIndicator(strokeWidth: 3)),
            const SizedBox(height: 14),
            AuroraText('正在加载游戏界面…', style: TextStyle(color: cs.onSurface.withValues(alpha: 0.8))),
          ] else ...[
            Icon(Icons.cloud_off, size: 36, color: cs.error),
            const SizedBox(height: 10),
            AuroraText('游戏界面加载失败，请检查网络', textAlign: TextAlign.center, style: TextStyle(color: cs.onSurface)),
            const SizedBox(height: 12),
            FilledButton.icon(onPressed: onRetry, icon: const Icon(Icons.refresh), label: const AuroraText('重试')),
          ],
        ]),
      ),
    );
  }
}
